	public static TexturedModelData create(String set) {
		return switch (set) {
			case "water" -> water();
			case "fire" -> fire();
			case "wind" -> wind();
			case "earth" -> earth();
			case "lightning" -> lightning();
			case "ice" -> ice();
			case "nature" -> nature();
			case "sound" -> sound();
			case "light" -> light();
			case "darkness" -> darkness();
			case "blood" -> blood();
			case "mana" -> mana();
			case "dragon" -> dragon();
			case "spirit" -> spirit();
			case "holy" -> holy();
			case "aura" -> aura();
			default -> throw new IllegalArgumentException(set);
		};
	}

